    21	/**
    22	 * REST Controller for Pet operations
    23	 */
    24	@RestController
    25	@RequestMapping("/api/pets")
    26	@Tag(name = "Pet", description = "Pet management API")
    27	@SecurityRequirement(name = "bearerAuth")
    28	public class PetRestController {
    29	
    30		private final OwnerRepository ownerRepository;
    31	
    32		private final PetTypeRepository petTypeRepository;
    33	
    34		public PetRestController(OwnerRepository ownerRepository, PetTypeRepository petTypeRepository) {
    35			this.ownerRepository = ownerRepository;
    36			this.petTypeRepository = petTypeRepository;
    37		}
    38	
    39		@GetMapping("/types")
    40		@Operation(summary = "Get all pet types", description = "Retrieve a list of all pet types")
    41		public Collection<PetType> getPetTypes() {
    42			return petTypeRepository.findPetTypes();
    43		}
    44	
    45		@GetMapping("/{petId}")
    46		@Operation(summary = "Get pet by ID", description = "Retrieve a specific pet by their ID")
    47		public ResponseEntity<Pet> getPet(@PathVariable @Parameter(description = "Pet ID") Integer petId) {
    48			// Find pet by searching through all owners
    49			for (Owner owner : ownerRepository.findAll()) {
    50				Pet pet = owner.getPet(petId);
    51				if (pet != null) {
    52					return ResponseEntity.ok(pet);
    53				}
    54			}
    55			return ResponseEntity.notFound().build();
    56		}
    57	
    58		@PostMapping
    59		@Operation(summary = "Create new pet", description = "Create a new pet for an owner")
    60		public ResponseEntity<Pet> createPet(@RequestBody Pet pet, @Parameter(description = "Owner ID") Integer ownerId) {
    61			Optional<Owner> ownerOpt = ownerRepository.findById(ownerId);
    62			if (ownerOpt.isEmpty()) {
    63				return ResponseEntity.notFound().build();
    64			}
    65	
    66			Owner owner = ownerOpt.get();
    67			owner.addPet(pet);
    68			ownerRepository.save(owner);
    69	
    70			return ResponseEntity.status(HttpStatus.CREATED).body(pet);
    71		}
    72	
    73		@PutMapping("/{petId}")
    74		@Operation(summary = "Update pet", description = "Update an existing pet")
    75		public ResponseEntity<Pet> updatePet(@PathVariable @Parameter(description = "Pet ID") Integer petId,
    76				@RequestBody Pet pet) {
    77			// Find and update pet
    78			for (Owner owner : ownerRepository.findAll()) {
    79				Pet existingPet = owner.getPet(petId);
    80				if (existingPet != null) {
    81					existingPet.setName(pet.getName());
    82					existingPet.setBirthDate(pet.getBirthDate());
    83					existingPet.setType(pet.getType());
    84					ownerRepository.save(owner);
    85					return ResponseEntity.ok(existingPet);
    86				}
    87			}
    88			return ResponseEntity.notFound().build();
    89		}
    90	
    91	}

