    58		@PostMapping
    59		@Operation(summary = "Create new pet", description = "Create a new pet for an owner")
    60		public ResponseEntity<Pet> createPet(@RequestBody Pet pet, @Parameter(description = "Owner ID") Integer ownerId) {
    61			Optional<Owner> ownerOpt = ownerRepository.findById(ownerId);
    62			if (ownerOpt.isEmpty()) {
    63				return ResponseEntity.notFound().build();
    64			}
    65	
    66			Owner owner = ownerOpt.get();
    67			owner.addPet(pet);
    68			ownerRepository.save(owner);
    69	
    70			return ResponseEntity.status(HttpStatus.CREATED).body(pet);
    71		}
