{
  "endpoint": {
    "method": "POST",
    "path": "/api/owners",
    "controller": "OwnerRestController",
    "controllerFile": "src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java",
    "handler": "createOwner"
  },
  "className": "OwnersCreateBlackBoxTest",
  "sqlSlug": "owners-create",
  "docLines": [
    "step3-B: /api/** requires Authorization: Bearer <jwt> (SecurityConfig). auth=bearer-token via /api/auth/login (admin/password).",
    "step3-C: no external HTTP calls -- OwnerRepository is a Spring Data JPA repository (in-process).",
