import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller VetController (src/main/java/org/springframework/samples/petclinic/vet/VetController.java)
 * @target-api GET /vets
 *
 * step3-B: /vets is NOT under /api/** in SecurityConfig -> falls through to .anyRequest().permitAll() -> no Authorization header required. analyze-auth-flow's generic 'jwt_or_bearer required' finding is a project-wide default that does not apply to this specific path; overridden per source review of SecurityConfig.authorizeHttpRequests().
 * step3-C: no external HTTP calls -- VetRepository is a Spring Data JPA repository (in-process).
 * step3-D: handler takes NO parameters at all (unlike showVetList(page, model) in the same class) -- there is no request-controllable branch to mutate/validate, so there is no meaningful VTC surface for black-box testing.
 * judgment call: the generic test-plan's 'ATC_code400' is a template default with no corresponding branch in this handler (plain findAll() + return) -- dropped rather than fabricate an unreachable test, per steering's 'source code overrides generic template' rule.
 * isolation: vets/specialties/vet_specialties are static reference data seeded by db/mysql/data.sql (spring.sql.init.mode=always, INSERT IGNORE, never mutated by any of the 8 endpoints under test) -- exact-value assertions against that fixed dataset are safe and deterministic, same treatment as the types table in PetsCreateBlackBoxTest.
 * assertions use RestAssured/Groovy 'list.find { }' GPath expressions instead of positional indices because JPA's findAll() does not guarantee row order.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class VetsHtmlControllerBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/vets-html-teardown.sql", p);
        executeSqlTemplate("sql/vets-html-setup.sql", p);
    }

    @Test
    void NTC_getVets_listSize(TestInfo info) {
        // data.sql seeds exactly 6 vets; this dataset is never mutated by any endpoint in scope
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.size()", equalTo(6));
        } finally {
            executeSqlTemplate("sql/vets-html-teardown.sql", p);
        }
    }

    @Test
    void NTC_getVets_specificVetFields(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.find { it.firstName == 'James' }.lastName", equalTo("Carter"))
                    .body("vetList.find { it.firstName == 'James' }.id", equalTo(1));
        } finally {
            executeSqlTemplate("sql/vets-html-teardown.sql", p);
        }
    }

    @Test
    void NTC_getVets_specialtiesPopulated(TestInfo info) {
        // Helen Leary (vet id=2) has exactly one specialty, radiology (specialty id=1), per vet_specialties (2,1) in data.sql
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.find { it.firstName == 'Helen' }.nrOfSpecialties", equalTo(1))
                    .body("vetList.find { it.firstName == 'Helen' }.specialties.find { it.name == 'radiology' }.id", equalTo(1));
        } finally {
            executeSqlTemplate("sql/vets-html-teardown.sql", p);
        }
    }
}
